#!/usr/bin/env python3
# Generated by nova via A2A Mesh delegation
"""
Mandatory provenance schema for every published conclusion in A2A Mesh.
Every conclusion published to the mesh MUST carry:
  - source_node:   identifier of the originating node
  - derived_at:    ISO-8601 timestamp of derivation
  - trust_score:   float [0.0, 1.0] confidence/trust metric

This module provides:
  - Provenance dataclass (the schema itself)
  - ProvenanceValidator (validates any conclusion before publish)
  - ProvenanceEnforcer (decorator + context manager that blocks
    publication of conclusions lacking provenance)
  - EpisodicAnchorGuard (ensures conclusions never overwrite
    node-local episodic anchors)
  - CLI entry point for testing / demonstration
"""

from __future__ import annotations

import dataclasses
import json
import os
import sys
import time
import uuid
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Callable, Tuple

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

PROVENANCE_FIELDS: Tuple[str, ...] = ("source_node", "derived_at", "trust_score")
TRUST_MIN: float = 0.0
TRUST_MAX: float = 1.0
DEFAULT_NODE_ID: str = os.environ.get("A2A_NODE_ID", "nova")
EPIODIC_ANCHOR_PREFIX: str = "episodic_anchor::"

# ---------------------------------------------------------------------------
# Schema
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class Provenance:
    """Mandatory provenance label attached to every published conclusion."""
    source_node: str
    derived_at: str          # ISO-8601 UTC
    trust_score: float       # 0.0 .. 1.0

    def __post_init__(self) -> None:
        # Validate at construction time
        if not self.source_node or not isinstance(self.source_node, str):
            raise ValueError("source_node must be a non-empty string")
        if not isinstance(self.trust_score, (int, float)):
            raise ValueError("trust_score must be numeric")
        if not (TRUST_MIN <= self.trust_score <= TRUST_MAX):
            raise ValueError(
                f"trust_score must be in [{TRUST_MIN}, {TRUST_MAX}], "
                f"got {self.trust_score}"
            )
        # Ensure derived_at is parseable ISO-8601
        try:
            datetime.fromisoformat(self.derived_at)
        except ValueError as exc:
            raise ValueError(f"derived_at must be ISO-8601, got '{self.derived_at}'") from exc

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), sort_keys=True)

    @classmethod
    def now(
        cls,
        source_node: str = DEFAULT_NODE_ID,
        trust_score: float = 0.5,
    ) -> "Provenance":
        """Create a Provenance with the current UTC timestamp."""
        return cls(
            source_node=source_node,
            derived_at=datetime.now(timezone.utc).isoformat(),
            trust_score=float(trust_score),
        )

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Provenance":
        return cls(
            source_node=d["source_node"],
            derived_at=d["derived_at"],
            trust_score=float(d["trust_score"]),
        )


# ---------------------------------------------------------------------------
# Conclusion wrapper
# ---------------------------------------------------------------------------

@dataclass
class Conclusion:
    """A published conclusion with mandatory provenance."""
    id: str
    content: str
    provenance: Provenance
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "content": self.content,
            "provenance": self.provenance.to_dict(),
            "metadata": self.metadata,
        }

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), sort_keys=True)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Conclusion":
        return cls(
            id=d["id"],
            content=d["content"],
            provenance=Provenance.from_dict(d["provenance"]),
            metadata=d.get("metadata", {}),
        )


# ---------------------------------------------------------------------------
# Validator
# ---------------------------------------------------------------------------

class ProvenanceValidator:
    """Validates that a conclusion (dict or Conclusion) carries full provenance."""

    @staticmethod
    def validate(obj: Any) -> List[str]:
        """Return list of error messages (empty == valid)."""
        errors: List[str] = []

        if isinstance(obj, Conclusion):
            return ProvenanceValidator._validate_provenance(obj.provenance)

        if isinstance(obj, Provenance):
            return ProvenanceValidator._validate_provenance(obj)

        if not isinstance(obj, dict):
            return ["object must be a dict, Conclusion, or Provenance"]

        prov = obj.get("provenance")
        if prov is None:
            errors.append("missing 'provenance' key")
            return errors

        if not isinstance(prov, dict):
            errors.append("'provenance' must be a dict")
            return errors

        for field_name in PROVENANCE_FIELDS:
            if field_name not in prov:
                errors.append(f"provenance missing required field: {field_name}")

        if errors:
            return errors

        # Field-level checks
        if not prov.get("source_node"):
            errors.append("source_node must be non-empty")
        try:
            ts = float(prov.get("trust_score", -1))
            if not (TRUST_MIN <= ts <= TRUST_MAX):
                errors.append(f"trust_score out of range [{TRUST_MIN},{TRUST_MAX}]")
        except (TypeError, ValueError):
            errors.append("trust_score must be numeric")
        try:
            datetime.fromisoformat(str(prov.get("derived_at", "")))
        except ValueError:
            errors.append("derived_at must be ISO-8601")

        return errors

    @staticmethod
    def _validate_provenance(prov: Provenance) -> List[str]:
        # Provenance.__post_init__ already validates, but double-check
        try:
            Provenance(
                source_node=prov.source_node,
                derived_at=prov.derived_at,
                trust_score=prov.trust_score,
            )
            return []
        except ValueError as exc:
            return [str(exc)]

    @staticmethod
    def is_valid(obj: Any) -> bool:
        return len(ProvenanceValidator.validate(obj)) == 0


# ---------------------------------------------------------------------------
# Episodic anchor guard
# ---------------------------------------------------------------------------

class EpisodicAnchorGuard:
    """
    Ensures that incoming conclusions NEVER overwrite node-local
    episodic anchors.  Episodic anchors are stored under keys
    prefixed with 'episodic_anchor::'.

    The guard wraps a key-value store (dict-like) and intercepts
    writes that would clobber an existing episodic anchor.
    """

    def __init__(self, store: Optional[Dict[str, Any]] = None) -> None:
        self._store: Dict[str, Any] = store if store is not None else {}
        self._violations: List[str] = []

    @property
    def store(self) -> Dict[str, Any]:
        return self._store

    @property
    def violations(self) -> List[str]:
        return list(self._violations)

    def is_episodic_anchor(self, key: str) -> bool:
        return key.startswith(EPIODIC_ANCHOR_PREFIX)

    def write(self, key: str, value: Any) -> bool:
        """
        Attempt to write *value* under *key*.
        Returns True if the write succeeded, False if it was blocked
        because it would overwrite an episodic anchor.
        """
        if self.is_episodic_anchor(key) and key in self._store:
            msg = (
                f"BLOCKED: attempted overwrite of episodic anchor '{key}'. "
                f"Conclusions may never overwrite node-local episodic facts."
            )
            self._violations.append(msg)
            return False
        self._store[key] = value
        return True

    def write_conclusion(self, conclusion: Conclusion) -> bool:
        """Store a conclusion under conclusion:{id}, guarded."""
        key = f"conclusion::{conclusion.id}"
        return self.write(key, conclusion.to_dict())

    def read(self, key: str) -> Optional[Any]:
        return self._store.get(key)

    def list_conclusions(self) -> List[Dict[str, Any]]:
        return [
            v for k, v in self._store.items()
            if k.startswith("conclusion::")
        ]


# ---------------------------------------------------------------------------
# Enforcer — publish pipeline
# ---------------------------------------------------------------------------

class ProvenanceEnforcer:
    """
    Central publish pipeline.  Any conclusion that goes through
    publish() is validated; if provenance is missing or invalid,
    the publish is rejected.
    """

    def __init__(
        self,
        node_id: str = DEFAULT_NODE_ID,
        guard: Optional[EpisodicAnchorGuard] = None,
    ) -> None:
        self.node_id = node_id
        self.guard = guard or EpisodicAnchorGuard()
        self._published: List[Conclusion] = []
        self._rejected: List[Tuple[Any, List[str]]] = []

    @property
    def published(self) -> List[Conclusion]:
        return list(self._published)

    @property
    def rejected(self) -> List[Tuple[Any, List[str]]]:
        return list(self._rejected)

    def publish(
        self,
        content: str,
        trust_score: float = 0.5,
        source_node: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
        conclusion_id: Optional[str] = None,
    ) -> Conclusion:
        """
        Publish a conclusion with mandatory provenance.
        Raises ValueError if provenance is invalid.
        """
        prov = Provenance.now(
            source_node=source_node or self.node_id,
            trust_score=trust_score,
        )
        conclusion = Conclusion(
            id=conclusion_id or str(uuid.uuid4()),
            content=content,
            provenance=prov,
            metadata=metadata or {},
        )
        errors = ProvenanceValidator.validate(conclusion)
        if errors:
            self._rejected.append((conclusion.to_dict(), errors))
            raise ValueError(f"Provenance validation failed: {errors}")

        ok = self.guard.write_conclusion(conclusion)
        if not ok:
            self._rejected.append((conclusion.to_dict(), ["episodic anchor overwrite blocked"]))
            raise ValueError("Publish blocked: episodic anchor overwrite attempt")

        self._published.append(conclusion)
        return conclusion

    def publish_raw(self, raw: Dict[str, Any]) -> Conclusion:
        """
        Publish a raw dict conclusion.  The dict must contain
        'content' and 'provenance' (with all three fields).
        """
        errors = ProvenanceValidator.validate(raw)
        if errors:
            self._rejected.append((raw, errors))
            raise ValueError(f"Provenance validation failed: {errors}")

        conclusion = Conclusion.from_dict(raw)
        ok = self.guard.write_conclusion(conclusion)
        if not ok:
            self._rejected.append((raw, ["episodic anchor overwrite blocked"]))
            raise ValueError("Publish blocked: episodic anchor overwrite attempt")

        self._published.append(conclusion)
        return conclusion

    def receive_from_mesh(self, raw: Dict[str, Any]) -> Conclusion:
        """
        Receive a conclusion from the mesh (another node).
        Validates provenance before accepting.
        The 768↔1024d re-encoding is conceptual: each node re-interprets
        in its own space, so we store a copy with our node_id as receiver.
        """
        errors = ProvenanceValidator.validate(raw)
        if errors:
            self._rejected.append((raw, errors))
            raise ValueError(f"Incoming conclusion rejected (no provenance): {errors}")

        conclusion = Conclusion.from_dict(raw)
        # Mark that this node received it (re-interpretation in own space)
        conclusion.metadata["received_by"] = self.node_id
        conclusion.metadata["received_at"] = datetime.now(timezone.utc).isoformat()

        ok = self.guard.write_conclusion(conclusion)
        if not ok:
            self._rejected.append((raw, ["episodic anchor overwrite blocked"]))
            raise ValueError("Receive blocked: episodic anchor overwrite attempt")

        self._published.append(conclusion)
        return conclusion


# ---------------------------------------------------------------------------
# Convenience decorator
# ---------------------------------------------------------------------------

def requires_provenance(func: Callable) -> Callable:
    """
    Decorator for functions that return a conclusion dict.
    The returned dict is validated; if provenance is missing,
    a ValueError is raised.
    """
    def wrapper(*args, **kwargs) -> Any:
        result = func(*args, **kwargs)
        errors = ProvenanceValidator.validate(result)
        if errors:
            raise ValueError(
                f"{func.__name__} returned a conclusion without valid provenance: {errors}"
            )
        return result
    wrapper.__name__ = func.__name__
    wrapper.__doc__ = func.__doc__
    return wrapper


# ---------------------------------------------------------------------------
# Demo / CLI
# ---------------------------------------------------------------------------

def _demo() -> None:
    print("=" * 70)
    print("A2A Mesh — Mandatory Provenance Schema Demo")
    print("=" * 70)

    enforcer = ProvenanceEnforcer(node_id="tor")

    # --- 1. Valid publish ---
    print("\n[1] Publishing a valid conclusion from node 'tor'...")
    c1 = enforcer.publish(
        content="A híd csak akkor véd, ha conclusions provenance-címkét kapnak.",
        trust_score=0.82,
        source_node="tor",
    )
    print(f"    ✓ Published: id={c1.id[:8]}...  provenance={c1.provenance.to_json()}")

    # --- 2. Receive from mesh (another node) ---
    print("\n[2] Receiving a conclusion from node 'runa' via mesh...")
    incoming = {
        "id": str(uuid.uuid4()),
        "content": "A 768↔1024d újrakódolás kizárja a direkt kontaminációt.",
        "provenance": {
            "source_node": "runa",
            "derived_at": datetime.now(timezone.utc).isoformat(),
            "trust_score": 0.71,
        },
        "metadata": {},
    }
    c2 = enforcer.receive_from_mesh(incoming)
    print(f"    ✓ Received:  id={c2.id[:8]}...  source={c2.provenance.source_node}  "
          f"received_by={c2.metadata['received_by']}")

    # --- 3. Reject conclusion without provenance ---
    print("\n[3] Attempting to publish a raw dict WITHOUT provenance...")
    bad = {"id": "x", "content": "no provenance here", "metadata": {}}
    try:
        enforcer.publish_raw(bad)
    except ValueError as exc:
        print(f"    ✓ Rejected (as expected): {exc}")

    # --- 4. Reject conclusion with invalid trust_score ---
    print("\n[4] Attempting to publish with trust_score=1.5 (out of range)...")
    bad2 = {
        "id": "y",
        "content": "bad trust",
        "provenance": {
            "source_node": "tor",
            "derived_at": datetime.now(timezone.utc).isoformat(),
            "trust_score": 1.5,
        },
    }
    try:
        enforcer.publish_raw(bad2)
    except ValueError as exc:
        print(f"    ✓ Rejected (as expected): {exc}")

    # --- 5. Episodic anchor guard ---
    print("\n[5] Testing episodic anchor overwrite protection...")
    guard = enforcer.guard
    # Simulate an existing episodic anchor
    anchor_key = "episodic_anchor::tor_cop_2026_09_18"
    guard.write(anchor_key, {"event": "COP repair", "ts": "2026-09-18T07:00:00Z"})
    print(f"    Episodic anchor stored: {anchor_key}")
    # Attempt to overwrite
    blocked = guard.write(anchor_key, {"event": "OVERWRITE ATTEMPT"})
    print(f"    Overwrite attempt blocked: {not blocked}  (write returned {blocked})")
    if guard.violations:
        print(f"    Violation logged: {guard.violations[-1]}")

    # --- 6. Summary ---
    print("\n" + "=" * 70)
    print("SUMMARY")
    print("=" * 70)
    print(f"  Published conclusions : {len(enforcer.published)}")
    print(f"  Rejected conclusions  : {len(enforcer.rejected)}")
    print(f"  Episodic violations   : {len(guard.violations)}")
    for c in enforcer.published:
        p = c.provenance
        print(f"    [{p.source_node:>8}] trust={p.trust_score:.2f}  "
              f"derived={p.derived_at[:19]}  content=\"{c.content[:50]}...\"")

    # --- 7. Serialize / deserialize round-trip ---
    print("\n[7] Serialization round-trip test...")
    json_str = c1.to_json()
    restored = Conclusion.from_dict(json.loads(json_str))
    assert restored.provenance.source_node == c1.provenance.source_node
    assert restored.provenance.trust_score == c1.provenance.trust_score
    print(f"    ✓ Round-trip OK: {restored.provenance.to_json()}")

    print("\nAll checks passed.\n")


if __name__ == "__main__":
    _demo()